{"result":"{
  "metadata": {
    "id": "302776322",
    "title": "04.1.8 Product, Catalogue and PDP",
    "type": "page",
    "created": "",
    "updated": "",
    "url": "https://zimmermannworkboard.atlassian.net/wiki/spaces/SFCC/pages/302776322",
    "space": {
      "key": "SFCC",
